objs=[list(o) for o in objs0]
def overlap(a,b): return not (a[0]+4 < b[0] or b[0]+4 < a[0] or a[1]+4 < b[1] or b[1]+4 < a[1])
for t in range(40):
    candidates=[]
    for i,o in enumerate(objs):
        dr=0; dc=1 if o[2]==2 else -1
        new=[o[0],o[1]+dc,o[2],o[3]]
        if new[1]<0 or new[1]+4>=22: candidates.append(False); continue
        blocked=any(j!=i and overlap(new,p) for j,p in enumerate(objs))
        candidates.append(not blocked)
    if not any(candidates): break
    for i,ok in enumerate(candidates):
      if ok: objs[i][1]+= (1 if objs[i][2]==2 else -1)
print(t,objs)

